from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_person_movie_credits import Get_person_movie_credits

import traceback

DIRECTOR_NAME = "SOFIA COPPOLA"
DIRECTOR_JOB = "DIRECTOR"

def search_director():
    response = Search_person(query=DIRECTOR_NAME.lower())
    results = response.get("results", [])
    for person in results:
        if person.get("name", "").lower() == DIRECTOR_NAME.lower():
            return person.get("id")
    return None

def get_directed_movies(person_id):
    movie_credits = Get_person_movie_credits(person_id=person_id)
    crew = movie_credits.get("crew", [])
    directed_movies = [movie for movie in crew if movie.get("job", "").lower() == DIRECTOR_JOB.lower()]
    return directed_movies

def count_directed_movies(movie_credits):
    return len(movie_credits)

def main():
    try:
        director_id = search_director()
        if director_id is None:
            print("Director not found.")
            return
        credits = get_directed_movies(director_id)
        count = count_directed_movies(credits)
        print(f"Number of movies directed by {DIRECTOR_NAME}: {count}")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

