import traceback

COLLECTION_QUERY = 'Star Wars'
IMAGE_SIZE = 'original'

def search_collection(query):
    response = Search_collections(query)
    results = response['results']
    if results:
        return results[0]['id']
    return None

def get_collection_details(collection_id):
    return Get_collection_details(collection_id)

def get_collection_image(collection_details):
    collection_id = collection_details['id']
    response = Get_collection_images(collection_id)
    posters = response['posters']
    if posters:
        return f"https://image.tmdb.org/t/p/{IMAGE_SIZE}{posters[0]['file_path']}"
    backdrops = response['backdrops']
    if backdrops:
        return f"https://image.tmdb.org/t/p/{IMAGE_SIZE}{backdrops[0]['file_path']}"
    return None

