from Search_movie import Search_movie
from Get_movie_details import Get_movie_details
from Get_movie_similar import Get_movie_similar
from Get_movie_reviews import Get_movie_reviews

import traceback

QUERY_TITANIC = "Titanic"
MAX_SIMILAR_MOVIES = 5
MAX_REVIEWS_PER_MOVIE = 3

def extract_id_from_search_result(search_result):
    results = search_result.get("results", [])
    if results:
        return results[0].get("id")
    return None

def extract_id_from_movie_details(movie_details):
    return movie_details.get("id")

def extract_id_from_similar_movie(similar_movie):
    return similar_movie.get("id")

def search_titanic():
    return Search_movie(QUERY_TITANIC)

def get_titanic_details(movie_search_result):
    movie_id = extract_id_from_search_result(movie_search_result)
    if movie_id is None:
        raise ValueError("Failed to extract movie ID from search result")
    return Get_movie_details(movie_id)

def find_similar_movies(movie_details):
    movie_id = extract_id_from_movie_details(movie_details)
    similar_movies_result = Get_movie_similar(movie_id)
    similar_movies = similar_movies_result.get("results", [])[:MAX_SIMILAR_MOVIES]
    return similar_movies

def get_reviews_of_similar_movies(similar_movies):
    reviews = []
    for similar_movie in similar_movies:
        movie_id = extract_id_from_similar_movie(similar_movie)
        movie_reviews_result = Get_movie_reviews(movie_id)
        movie_reviews = movie_reviews_result.get("results", [])[:MAX_REVIEWS_PER_MOVIE]
        reviews.extend(movie_reviews)
    return reviews

def main():
    try:
        search_result = search_titanic()
        movie_details = get_titanic_details(search_result)
        similar_movies = find_similar_movies(movie_details)
        reviews = get_reviews_of_similar_movies(similar_movies)
        for review in reviews:
            print(f"Author: {review.get('author')}")
            print(f"Content: {review.get('content')}")
            print("-" * 80)
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

