from Search_movie import Search_movie
from Get_movie_recommendations import Get_movie_recommendations
from Get_movie_details import Get_movie_details

import traceback

QUERY_TITANIC = "Titanic"
RECOMMENDATIONS_COUNT = 5

def search_for_movie_titanic():
    response = Search_movie(QUERY_TITANIC)
    results = response.get("results", [])
    if results:
        return results[0].get("id")
    return None

def get_recommendations(movie_id):
    response = Get_movie_recommendations(movie_id)
    return response.get("results", [])[:RECOMMENDATIONS_COUNT]

def get_movie_details(recommended_movies):
    movie_details = []
    for movie in recommended_movies:
        movie_id = movie.get("id")
        if movie_id:
            details = Get_movie_details(movie_id)
            movie_details.append({
                "title": details.get("title"),
                "overview": details.get("overview"),
                "release_date": details.get("release_date"),
                "vote_average": details.get("vote_average")
            })
    return movie_details

def main():
    try:
        movie_id = search_for_movie_titanic()
        if movie_id is None:
            print("Failed to find Titanic movie ID.")
            return

        recommended_movies = get_recommendations(movie_id)
        movie_details = get_movie_details(recommended_movies)

        print("Movie Recommendations:")
        for movie in movie_details:
            print(f"Title: {movie['title']}")
            print(f"Overview: {movie['overview']}")
            print(f"Release Date: {movie['release_date']}")
            print(f"Vote Average: {movie['vote_average']}\n")

    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

