from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_details import Get_movie_details

import traceback

DIRECTOR_NAME = "Christopher Nolan"
JOB_DIRECTOR = "Director"

def search_director():
    response = Search_person(query=DIRECTOR_NAME)
    results = response.get("results", [])
    for person in results:
        if person.get("name") == DIRECTOR_NAME:
            return person.get("id")
    return None

def get_director_credits(person_id):
    return Get_person_movie_credits(person_id=person_id)

def identify_latest_movie(movie_credits):
    latest_movie = None
    latest_release_date = None
    crew = movie_credits.get("crew", [])
    for credit in crew:
        if credit.get("job") == JOB_DIRECTOR:
            movie_id = credit.get("id")
            movie_details = Get_movie_details(movie_id=movie_id)
            release_date = movie_details.get("release_date")
            if release_date and (not latest_release_date or release_date > latest_release_date):
                latest_release_date = release_date
                latest_movie = movie_details
    return latest_movie

def main():
    director_id = search_director()
    if director_id is None:
        print("Director not found.")
        return
    credits = get_director_credits(director_id)
    latest_movie = identify_latest_movie(credits)
    if latest_movie:
        print(latest_movie.get("title"))
    else:
        print("No movies found.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

