import traceback

DIRECTOR_NAME = "Martin Scorsese"
REGION = None

def search_director():
    response = Search_person(query=DIRECTOR_NAME)
    results = response.get("results", [])
    if results:
        return results[0].get("id")
    return None

def get_director_movie_credits(director_id):
    response = Get_person_movie_credits(person_id=director_id)
    return response.get("crew", [])

def extract_directed_movies(movie_credits):
    directed_movies = [movie for movie in movie_credits if movie.get("job") == "Director"]
    return directed_movies

def get_top_rated_movies():
    response = Get_top_rated_movies(region=REGION)
    return response.get("results", [])

def find_highest_rated_directed_movie(directed_movies, top_rated_movies):
    directed_movie_ids = {movie["id"] for movie in directed_movies}
    for movie in top_rated_movies:
        if movie["id"] in directed_movie_ids:
            return movie
    return None

def main():
    try:
        director_id = search_director()
        if director_id is None:
            print("Director not found.")
            return

        movie_credits = get_director_movie_credits(director_id)
        directed_movies = extract_directed_movies(movie_credits)
        top_rated_movies = get_top_rated_movies()
        highest_rated_directed_movie = find_highest_rated_directed_movie(directed_movies, top_rated_movies)

        if highest_rated_directed_movie:
            print(f"Title: {highest_rated_directed_movie.get('title')}")
            print(f"Rating: {highest_rated_directed_movie.get('vote_average')}")
        else:
            print("No directed movie found in top-rated movies.")
