from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_credits import Get_movie_credits

import traceback

PERSON_NAME = "Leonardo DiCaprio"
DIRECTOR_JOB_TITLE = "Director"

def lookup_person_id(name):
    # This function is not directly provided, so we'll assume it's implemented elsewhere
    # For demonstration purposes, let's assume Leonardo DiCaprio's ID is 6193
    if name == PERSON_NAME:
        return 6193
    else:
        raise ValueError(f"Person {name} not found")

def extract_latest_movie(movie_credits):
    cast = movie_credits.get("cast", [])
    if not cast:
        raise ValueError("No cast information available")
    latest_movie = max(cast, key=lambda x: x.get("release_date", ""))
    return latest_movie

def extract_director(movie_credits):
    crew = movie_credits.get("crew", [])
    if not crew:
        raise ValueError("No crew information available")
    directors = [member for member in crew if member.get("job") == DIRECTOR_JOB_TITLE]
    if not directors:
        raise ValueError(f"No {DIRECTOR_JOB_TITLE} found in the crew")
    return directors[0]

def get_latest_movie_featuring_leonardo_dicaprio():
    person_id = lookup_person_id(PERSON_NAME)
    movie_credits = Get_person_movie_credits(person_id)
    latest_movie = extract_latest_movie(movie_credits)
    return latest_movie.get("id")

def identify_director_of_movie(movie_id):
    movie_credits = Get_movie_credits(movie_id)
    director = extract_director(movie_credits)
    return director.get("name")

def main():
    try:
        latest_movie_id = get_latest_movie_featuring_leonardo_dicaprio()
        director_name = identify_director_of_movie(latest_movie_id)
        print(director_name)
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

