import traceback

DIRECTOR_NAME = "Catherine Hardwicke"

def search_person(query):
    response = Search_person(query)
    results = response.get("results", [])
    if results:
        return results[0].get("id")
    return None

def get_person_tv_credits(person_id):
    response = Get_person_tv_credits(person_id)
    crew_credits = response.get("crew", [])
    return crew_credits

def get_recent_tv_details(tv_credits):
    tv_credits.sort(key=lambda x: x.get("first_air_date", ""), reverse=True)
    recent_tv_id = tv_credits[0].get("id")
    return Get_tv_details(recent_tv_id)

def main():
    person_id = search_person(DIRECTOR_NAME)
    if person_id is None:
        print(f"Director '{DIRECTOR_NAME}' not found.")
        return

    tv_credits = get_person_tv_credits(person_id)
    if not tv_credits:
        print(f"No TV credits found for director '{DIRECTOR_NAME}'.")
        return

    recent_tv_details = get_recent_tv_details(tv_credits)
    print(recent_tv_details.get("name"))

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

