import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_season_details import Get_tv_season_details
from Get_tv_episode_details import Get_tv_episode_details
from Get_tv_episode_images import Get_tv_episode_images

import traceback

# Constants derived from user_requirement
TV_SHOW_NAME = "The Witcher"
SEASON_NUMBER = 1
EPISODE_NUMBER = 2

def search_for_tv_show(query):
    """Search for a TV show by query."""
    response = Search_tv(query=query)
    results = response.get("results", [])
    if results:
        return results[0]
    return None

def get_tv_show_details(tv_show_result):
    """Get details of a TV show using its ID."""
    series_id = tv_show_result.get("id")
    if series_id is not None:
        return Get_tv_details(series_id=series_id)
    return None

def get_season_details(tv_show_details):
    """Get details of a specific season of a TV show."""
    series_id = tv_show_details.get("id")
    season_number = SEASON_NUMBER
    if series_id is not None:
        return Get_tv_season_details(series_id=series_id, season_number=season_number)
    return None

def get_episode_details(season_details):
    """Get details of a specific episode in a season."""
    series_id = season_details.get("id")
    season_number = season_details.get("season_number")
    episodes = season_details.get("episodes", [])
    if len(episodes) >= EPISODE_NUMBER:
        episode_number = EPISODE_NUMBER
        episode_details = Get_tv_episode_details(series_id=series_id, season_number=season_number, episode_number=episode_number)
        return episode_details
    return None

def get_episode_images(episode_details):
    """Get images for a specific TV episode."""
    series_id = episode_details.get("show_id")
    season_number = episode_details.get("season_number")
    episode_number = episode_details.get("episode_number")
    if series_id is not None and season_number is not None and episode_number is not None:
        return Get_tv_episode_images(series_id=series_id, season_number=season_number, episode_number=episode_number)
    return None

def main():
    try:
        tv_show_result = search_for_tv_show(query=TV_SHOW_NAME)
        if tv_show_result is None:
            print("TV show not found.")
            return

        tv_show_details = get_tv_show_details(tv_show_result)
        if tv_show_details is None:
            print("Failed to retrieve TV show details.")
            return

        season_details = get_season_details(tv_show_details)
        if season_details is None:
            print("Failed to retrieve season details.")
            return

        episode_details = get_episode_details(season_details)
        if episode_details is None:
            print("Failed to retrieve episode details.")
            return

        episode_images = get_episode_images(episode_details)
        if episode_images is not None:
            stills = episode_images.get("stills", [])
            if stills:
                image_path = stills[0].get("file_path")
                if image_path:
                    print(f"https://image.tmdb.org/t/p/original{image_path}")
                else:
                    print("No image path found.")
            else:
                print("No still images found for the episode.")
        else:
            print("Failed to retrieve episode images.")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

