from Search_movie import Search_movie
from Get_movie_release_dates import Get_movie_release_dates

import traceback

MOVIE_TITLE = "The Matrix"
QUERY = "The Matrix"

def extract_movie_id(search_results):
    for result in search_results.get("results", []):
        if result.get("title").lower() == MOVIE_TITLE.lower():
            return result.get("id")
    return None

def get_release_date(release_dates_response):
    results = release_dates_response.get("results", [])
    for result in results:
        release_dates = result.get("release_dates", [])
        for release_date in release_dates:
            if release_date.get("type") == 3: 
                return release_date.get("release_date")
    return None

def main():
    try:
        search_results = Search_movie(QUERY)
        movie_id = extract_movie_id(search_results)
        if movie_id is None:
            print("Movie not found.")
            return
