import requests
import traceback



MAX_RESULTS = 1
MAX_RETRIES = 3

def get_most_popular_movie():
    retries = 0
    while retries < MAX_RETRIES:
        try:
            response = Get_popular_movie()
            results = response['results']
            if results:
                most_popular_movie = results[0]
                return most_popular_movie
            else:
                return None
        except requests.exceptions.ConnectionError as e:
            retries += 1
            if retries == MAX_RETRIES:
                raise Exception(f"API request failed after {MAX_RETRIES} retries: {e}")
        except Exception as e:
            raise Exception(f"API request failed: {e}")

def get_movie_keywords(movie_id):
    retries = 0
    while retries < MAX_RETRIES:
        try:
            response = Get_movie_keywords(movie_id)
            keywords = response['keywords']
            return keywords
        except requests.exceptions.ConnectionError as e:
            retries += 1
            if retries == MAX_RETRIES:
                raise Exception(f"API request failed after {MAX_RETRIES} retries: {e}")
        except Exception as e:
            raise Exception(f"API request failed: {e}")

def main():
    try:
        most_popular_movie = get_most_popular_movie()
        if most_popular_movie is not None:
            movie_id = most_popular_movie['id']
            movie_keywords = get_movie_keywords(movie_id)
            print("Most Popular Movie:")
            print(f"Title: {most_popular_movie['title']}")
            print(f"ID: {most_popular_movie['id']}")
            print("Keywords:")
            for keyword in movie_keywords:
                print(f"- {keyword['name']}")
        else:
            print("No popular movies found.")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

