from Get_popular_movie import Get_popular_movie
from Get_movie_keywords import Get_movie_keywords

import traceback

POPULAR_MOVIES_PAGE = 1
KEYWORD_JOIN_SEPARATOR = ", "


def get_most_popular_movie():
    try:
        response = Get_popular_movie()
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch popular movies: {exc}")

    results = response.get("results", [])
    if not results:
        return None

    # The API already returns movies ordered by popularity, so take the first one.
    return results[0]


def get_movie_keywords_for_movie(movie):
    if not movie:
        return None

    movie_id = movie.get("id")
    if movie_id is None:
        return None

    try:
        return Get_movie_keywords(movie_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch keywords for movie ID {movie_id}: {exc}")


def extract_keyword_names(keywords_response):
    if not keywords_response:
        return []

    keywords = keywords_response.get("keywords", [])
    names = []
    for keyword in keywords:
        name = keyword.get("name")
        if name:
            names.append(name)
    return names


def format_keywords(movie, keyword_names):
    title = movie.get("title") or movie.get("original_title") or "Unknown movie"
    if not keyword_names:
        return f"The most popular movie right now is '{title}', but no keywords were returned."

    return f"The keywords of '{title}' are: {KEYWORD_JOIN_SEPARATOR.join(keyword_names)}"


def main():
    movie = get_most_popular_movie()
    if movie is None:
        print("No popular movies were returned.")
        return

    keywords_response = get_movie_keywords_for_movie(movie)
    keyword_names = extract_keyword_names(keywords_response)
    output = format_keywords(movie, keyword_names)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

