from Search_collections import Search_collections
from Get_collection_details import Get_collection_details
from Get_movie_release_dates import Get_movie_release_dates

import traceback

# Module-level constants pinned from user requirement / assumptions
COLLECTION_QUERY = "The Hobbit"
TARGET_COUNTRY_CODE = "US"


def select_matching_collection_identifier(collection_search_results, collection_name):
    """
    Select the most likely matching collection ID from search results.
    Uses a lenient name match against known schema keys.
    """
    results = collection_search_results.get("results", []) if isinstance(collection_search_results, dict) else []
    if not results:
        return None

    lowered_target = (collection_name or "").strip().lower()
    best_match_id = None

    for item in results:
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if lowered_target and (lowered_target in name or lowered_target in original_name or name in lowered_target or original_name in lowered_target):
            return item.get("id")

    # Fallback: first result's id, if any
    first = results[0]
    best_match_id = first.get("id")
    return best_match_id


def extract_movies_from_collection(collection_details):
    """
    Extract the 'parts' list from collection details, matching the response schema exactly.
    """
    if not isinstance(collection_details, dict):
        return []
    parts = collection_details.get("parts", [])
    if isinstance(parts, list):
        return parts
    return []


def extract_movie_identifier(movie):
    """
    Extract movie ID using the exact schema key 'id'.
    """
    if not isinstance(movie, dict):
        return None
    return movie.get("id")


def find_release_dates_for_movie(release_info, target_country_code=TARGET_COUNTRY_CODE):
    """
    From movie release dates response, extract release date strings for a target country.
    Exact schema keys used: 'results', 'iso_3166_1', 'release_dates', 'release_date'.
    """
    dates = []
    if not isinstance(release_info, dict):
        return dates

    results = release_info.get("results", [])
    if not isinstance(results, list):
        return dates

    target = str(target_country_code).strip().upper()

    for country_block in results:
        if not isinstance(country_block, dict):
            continue
        country_code = str(country_block.get("iso_3166_1", "")).strip().upper()
        if target and country_code != target:
            continue

        release_dates = country_block.get("release_dates", [])
        if not isinstance(release_dates, list):
            continue

        for entry in release_dates:
            if not isinstance(entry, dict):
                continue
            release_date = entry.get("release_date")
            if release_date:
                dates.append(release_date)

    return dates


def format_collection_release_dates(movie_release_data, collection_name=COLLECTION_QUERY):
    """
    Create readable output from a list of release date payloads.
    """
    lines = []
    lines.append(f"Release dates for the movies in the collection '{collection_name}':")

    if not movie_release_data:
        lines.append("No movies or release date data were found.")
        return "\n".join(lines)

    for movie_item in movie_release_data:
        movie_name = movie_item.get("movie_name", "Unknown title")
        release_dates = movie_item.get("release_dates", [])
        if release_dates:
            joined = ", ".join(release_dates)
            lines.append(f"- {movie_name}: {joined}")
        else:
            lines.append(f"- {movie_name}: No release dates found for {TARGET_COUNTRY_CODE}")

    return "\n".join(lines)


def find_collection_identifier(collection_name):
    collection_search_results = Search_collections(collection_name)
    collection_identifier = select_matching_collection_identifier(collection_search_results, collection_name)
    return collection_identifier


def get_collection_movies(collection_identifier):
    collection_details = Get_collection_details(collection_identifier)
    movie_list = extract_movies_from_collection(collection_details)
    return movie_list


def get_movie_release_info(movie_list):
    release_info_list = []
    for movie in movie_list:
        movie_identifier = extract_movie_identifier(movie)
        if movie_identifier is None:
            continue
        release_info = Get_movie_release_dates(movie_identifier)
        release_info_list.append(
            {
                "movie_name": movie.get("name", "Unknown title"),
                "release_dates": find_release_dates_for_movie(release_info, TARGET_COUNTRY_CODE),
            }
        )
    return release_info_list


def main():
    collection_identifier = find_collection_identifier(COLLECTION_QUERY)
    if collection_identifier is None:
        return f"No collection found for '{COLLECTION_QUERY}'."

    movie_list = get_collection_movies(collection_identifier)
    release_info_list = get_movie_release_info(movie_list)
    return format_collection_release_dates(release_info_list, COLLECTION_QUERY)


if __name__ == "__main__":
    try:
        result = main()
        if result is not None:
            print(result)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

