from Search_collections import Search_collections
from Get_collection_details import Get_collection_details

import traceback

COLLECTION_QUERY = "The Fast and the Furious"
TARGET_NAME_FRAGMENT = "Fast and the Furious"


def search_collection_by_name(query):
    try:
        return Search_collections(query)
    except Exception as exc:
        raise RuntimeError(f"Failed to search collections for query={query!r}") from exc


def select_target_collection(matching_collections):
    results = matching_collections.get("results", []) if isinstance(matching_collections, dict) else []
    if not results:
        return None

    target_lower = TARGET_NAME_FRAGMENT.lower()
    best_match = None

    for collection in results:
        name = str(collection.get("name", ""))
        original_name = str(collection.get("original_name", ""))
        haystack = f"{name} {original_name}".lower()
        if target_lower in haystack:
            best_match = collection
            break

    if best_match is None:
        best_match = results[0]

    return best_match.get("id")


def get_collection_items(collection_identifier):
    if collection_identifier is None:
        return {}
    try:
        return Get_collection_details(collection_identifier)
    except Exception as exc:
        raise RuntimeError(f"Failed to get collection details for collection_id={collection_identifier!r}") from exc


def extract_movies_from_collection(collection_details):
    if not isinstance(collection_details, dict):
        return []

    parts = collection_details.get("parts", [])
    movies = []

    for item in parts:
        if not isinstance(item, dict):
            continue
        movies.append(
            {
                "id": item.get("id"),
                "name": item.get("name"),
                "original_name": item.get("original_name"),
                "release_date": item.get("release_date"),
                "overview": item.get("overview"),
                "vote_average": item.get("vote_average"),
                "vote_count": item.get("vote_count"),
                "media_type": item.get("media_type"),
            }
        )

    return movies


def format_movies_output(collection_name, movies):
    lines = []
    header = f"Movies in {collection_name}:"
    lines.append(header)

    if not movies:
        lines.append("No movies found.")
        return "\n".join(lines)

    for idx, movie in enumerate(movies, start=1):
        title = movie.get("name") or movie.get("original_name") or "Unknown title"
        release_date = movie.get("release_date") or "Unknown release date"
        lines.append(f"{idx}. {title} ({release_date})")

    return "\n".join(lines)


def main():
    matching_collections = search_collection_by_name(COLLECTION_QUERY)
    collection_identifier = select_target_collection(matching_collections)
    collection_details = get_collection_items(collection_identifier)
    movies_list = extract_movies_from_collection(collection_details)

    collection_name = "The Fast and the Furious collection"
    if isinstance(collection_details, dict) and collection_details.get("name"):
        collection_name = collection_details.get("name")

    print(format_movies_output(collection_name, movies_list))


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

