from Get_collection_details import Get_collection_details
from Get_movie_details import Get_movie_details
from Get_movie_reviews import Get_movie_reviews

import requests
import time
import traceback



COLLECTION_QUERY = 'The Fast and the Furious'
MAX_RETRIES = 3
RETRY_DELAY = 1  # seconds

def search_collection():
    response = Search_collections(COLLECTION_QUERY)
    results = response['results']
    if results:
        return results[0]['id']
    return None

def get_collection_details(collection_id):
    return Get_collection_details(collection_id)

def get_movies_in_collection(collection_details):
    movie_ids = [movie['id'] for movie in collection_details['parts']]
    return [get_movie_details_with_retry(movie_id) for movie_id in movie_ids]

def get_movie_details_with_retry(movie_id):
    attempts = 0
    while attempts < MAX_RETRIES:
        try:
            return Get_movie_details(movie_id)
        except requests.exceptions.ConnectionError as e:
            attempts += 1
            if attempts < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                raise Exception(f"Failed to get movie details after {MAX_RETRIES} retries: {e}")

def get_movie_reviews(list_of_movie_details):
    if list_of_movie_details:
        selected_movie = list_of_movie_details[0]
        return Get_movie_reviews(selected_movie['id'])
    return None

def main():
    collection_id = search_collection()
    if collection_id is None:
        print("Collection not found.")
        return

    collection_details = get_collection_details(collection_id)
    list_of_movie_details = get_movies_in_collection(collection_details)
    movie_reviews = get_movie_reviews(list_of_movie_details)

    if movie_reviews and 'results' in movie_reviews:
        for review in movie_reviews['results']:
            print(f"Author: {review['author']}")
            print(f"Content: {review['content']}")
            print("-" * 80)

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

