def get_collection_details(search_result):
    results = search_result.get('results', [])
    if not results:
        raise ValueError("No collection found matching the query.")
    collection_id = results[0].get('id')
    if collection_id is None:
        raise ValueError("Collection ID not found in search results.")
    return Get_collection_details(collection_id=collection_id)

def get_first_movie_release_date(collection_details):
    parts = collection_details.get('parts', [])
    if not parts:
        raise ValueError("No movies found in the collection.")
    first_movie = min(parts, key=lambda x: x.get('release_date', '9999-99-99'))
    movie_id = first_movie.get('id')
    if movie_id is None:
        raise ValueError("First movie ID not found.")
    movie_details = Get_movie_details(movie_id=movie_id)
    return movie_details.get('release_date')

def main():
    try:
        search_result = search_collection(query=COLLECTION_QUERY)
        collection_details = get_collection_details(search_result=search_result)
        release_date = get_first_movie_release_date(collection_details=collection_details)
        print(release_date)
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

