from Search_tv import Search_tv
from Get_tv_season_details import Get_tv_season_details
from Get_tv_season_credits import Get_tv_season_credits

import traceback

SERIES_NAME = "House of Cards"
SEASON_NUMBER = 1
DIRECTOR_ROLE = "director"


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def select_matching_item(search_response, series_name):
    results = search_response.get("results", [])
    target = normalize_text(series_name)
    if not results:
        return None

    for item in results:
        name = normalize_text(item.get("name"))
        original_name = normalize_text(item.get("original_name"))
        if target in name or target in original_name:
            return item

    return results[0]


def find_series_id(series_name):
    search_result = Search_tv(query=series_name)
    series_item = select_matching_item(search_result, series_name)
    if not series_item:
        return None
    return series_item.get("id")


def get_first_season_details(series_id):
    if series_id is None:
        return None
    return Get_tv_season_details(series_id=series_id, season_number=SEASON_NUMBER)


def get_first_season_credits(series_id):
    if series_id is None:
        return None
    return Get_tv_season_credits(series_id=series_id, season_number=SEASON_NUMBER)


def extract_directors_from_credits(season_credits):
    directors = []
    crew = season_credits.get("crew", []) if isinstance(season_credits, dict) else []
    for member in crew:
        job = normalize_text(member.get("job"))
        if DIRECTOR_ROLE in job:
            name = member.get("name")
            if name:
                directors.append(name)
    return directors


def derive_directors_from_season_details(season_details):
    directors = []
    episodes = season_details.get("episodes", []) if isinstance(season_details, dict) else []
    for episode in episodes:
        crew = episode.get("crew", [])
        for member in crew:
            department = normalize_text(member.get("department"))
            job = normalize_text(member.get("job"))
            if DIRECTOR_ROLE in department or DIRECTOR_ROLE in job:
                name = member.get("name")
                if name and name not in directors:
                    directors.append(name)
    return directors


def extract_directors(season_details, season_credits):
    directors = extract_directors_from_credits(season_credits)
    if not directors:
        directors = derive_directors_from_season_details(season_details)
    return directors


def format_output(directors):
    if not directors:
        return "No directors found for the first season."
    return "Directors of the first season of House of Cards:\n" + "\n".join(f"- {name}" for name in directors)


def main():
    series_id = find_series_id(SERIES_NAME)
    season_details = get_first_season_details(series_id)
    season_credits = get_first_season_credits(series_id)
    directors = extract_directors(season_details, season_credits)
    return format_output(directors)


if __name__ == "__main__":
    try:
        output = main()
        print(output)
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

