from Get_movie_details import Get_movie_details
from Get_person_details import Get_person_details
from Get_person_movie_credits import Get_person_movie_credits

import requests
import os
import traceback


MOVIE_TITLE = "Django Unchained"
MAX_DIRECTED_MOVIES = 3
TMDB_BEARER_TOKEN = "your_tmdb_bearer_token"

def Search_movie(title):
    url = f"https://api.themoviedb.org/3/search/movie?query={title}"
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {TMDB_BEARER_TOKEN}"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        data = response.json()
        if data['results']:
            return data['results'][0]['id']
    raise Exception(f"Failed to find movie ID for '{title}'")

def Get_movie_credits(movie_id):
    url = f"https://api.themoviedb.org/3/movie/{movie_id}/credits"
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {TMDB_BEARER_TOKEN}"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}")

def Get_person_movie_credits(person_id):
    url = f"https://api.themoviedb.org/3/person/{person_id}/movie_credits"
    headers = {
        "accept": "application/json",
        "Authorization": f"Bearer {TMDB_BEARER_TOKEN}"
    }
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    raise Exception(f"API request failed with status code {response.status_code}")

def get_director_id(movie_id):
    movie_credits = Get_movie_credits(movie_id)
    crew = movie_credits.get("crew", [])
    for member in crew:
        if member.get("job") == "Director":
            return member.get("id")
    return None

def filter_directed_movies(movie_credits):
    directed_movies = []
    crew = movie_credits.get("crew", [])
    for credit in crew:
        if credit.get("job") == "Director":
            directed_movies.append({
                "title": credit.get("title"),
                "release_date": credit.get("release_date")
            })
    return directed_movies

def main():
    try:
        movie_id = Search_movie(MOVIE_TITLE)
        director_id = get_director_id(movie_id)
        if director_id is None:
            print("Director not found.")
            return
        movie_credits = Get_person_movie_credits(director_id)
        directed_movies = filter_directed_movies(movie_credits)
        for movie in directed_movies[:MAX_DIRECTED_MOVIES]:
            print(f"Title: {movie['title']}, Release Date: {movie['release_date']}")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

