    """Identify the lead actor from the TV show credits."""
    tv_show_id = tv_show_details.get("id")
    credits_response = Get_tv_latest_season_credits(tv_show_id)
    cast = credits_response.get("cast", [])
    lead_actor = next((actor for actor in cast if actor.get("known_for_department") == LEAD_ACTOR_DEPARTMENT), None)
    if lead_actor:
        return lead_actor.get("name")
    return None

