    if tv_show_result is None:
        print("TV show not found.")
        return

    production_company_id = get_production_company_id(tv_show_result)
    if production_company_id is None:
        print("Production company ID not found.")
        return

    founding_year_info = get_company_founding_year(production_company_id)
    print(founding_year_info)

