from Get_tv_episode_details import Get_tv_episode_details
from Get_tv_episode_images import Get_tv_episode_images

import traceback

TMDB_QUERY = "Band of Brothers"
EPISODE_NUMBER = 3

def search_tv_show():
    try:
        response = Search_tv(query=TMDB_QUERY)
        return response["results"]
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        return None

def get_tv_show_details(search_results):
    try:
        for result in search_results:
            if result["original_name"].lower() == TMDB_QUERY.lower():
                series_id = result["id"]
                return Get_tv_details(series_id=series_id)
        return None
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        return None

def get_tv_episode_details(tv_show_details):
    try:
        series_id = tv_show_details["id"]
        season_number = tv_show_details["seasons"][0]["season_number"]
        season_details = Get_tv_season_details(series_id=series_id, season_number=season_number)
        for episode in season_details["episodes"]:
            if episode["episode_number"] == EPISODE_NUMBER:
                return Get_tv_episode_details(series_id=series_id, season_number=season_number, episode_number=EPISODE_NUMBER)
        return None
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        return None

def get_episode_poster(tv_show_details, episode_details):
    try:
        series_id = tv_show_details["id"]
        season_number = episode_details["season_number"]
        episode_number = episode_details["episode_number"]
        episode_images = Get_tv_episode_images(series_id=series_id, season_number=season_number, episode_number=episode_number)
        if episode_images["stills"]:
            return episode_images["stills"][0]["file_path"]
        return None
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        return None

def main():
    TMDB_QUERY = "Band of Brothers"
    EPISODE_NUMBER = 3
    search_results = search_tv_show()
    if search_results is None:
        return
    tv_show_details = get_tv_show_details(search_results)
    if tv_show_details is None:
        return
    episode_details = get_tv_episode_details(tv_show_details)
    if episode_details is None:
        return
    episode_poster = get_episode_poster(tv_show_details, episode_details)
    if episode_poster is not None:
        print(episode_poster)

if __name__ == "__main__":
    main()

