import requests
import traceback



TMDB_IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original"
QUERY = "Game of Thrones"

def search_for_tv_show(query):
    try:
        response = Search_tv(query)
        results = response.get("results", [])
        if results:
            return results[0]
    except requests.exceptions.ConnectionError as e:
        print(f"Connection error occurred: {e}")
    return None

def get_network_details(tv_show_details):
    try:
        series_id = tv_show_details.get("id")
        if series_id is not None:
            response = Get_tv_details(series_id)
            networks = response.get("networks", [])
            if networks:
                return networks[0]
    except requests.exceptions.ConnectionError as e:
        print(f"Connection error occurred: {e}")
    return None

def get_network_logo(network_details):
    try:
        network_id = network_details.get("id")
        if network_id is not None:
            response = Get_network_images(network_id)
            logos = response.get("logos", [])
            if logos:
                logo_path = logos[0].get("file_path")
                return f"{TMDB_IMAGE_BASE_URL}{logo_path}"
    except requests.exceptions.ConnectionError as e:
        print(f"Connection error occurred: {e}")
    return None

def main():
    tv_show_details = search_for_tv_show(QUERY)
    if tv_show_details is None:
        print("TV show not found or connection error occurred.")
        return

    network_details = get_network_details(tv_show_details)
    if network_details is None:
        print("Network details not found or connection error occurred.")
        return

    network_logo = get_network_logo(network_details)
    if network_logo is None:
        print("Network logo not found or connection error occurred.")
        return

    print(network_logo)

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

