RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_person import Search_person
from Get_person_tv_credits import Get_person_tv_credits
from Get_tv_episode_credits import Get_tv_episode_credits

import traceback

SEARCH_QUERY_JEREMY_CLARKSON = "Jeremy Clarkson"
TARGET_SHOW_KEYWORDS = ["top gear", "the grand tour", "jeremy clarkson"]
MAX_RESULTS_TO_SCAN = 10
MAX_CREDITS_TO_SCAN = 10
DEFAULT_SEASON_NUMBER = 1
DEFAULT_EPISODE_NUMBER = 1


def safe_get(dct, *keys, default=None):
    cur = dct
    for key in keys:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur[key]
    return cur


def normalize_text(value):
    if value is None:
        return ""
    return str(value).strip().lower()


def search_jeremy_clarkson():
    data = Search_person(SEARCH_QUERY_JEREMY_CLARKSON)
    results = safe_get(data, "results", default=[])
    if not results:
        return None
    for person in results:
        name = normalize_text(person.get("name"))
        original_name = normalize_text(person.get("original_name"))
        if "jeremy clarkson" in name or "jeremy clarkson" in original_name:
            return person
    return results[0]


def get_most_popular_tv_show(person_record):
    if not person_record:
        return None

    person_id = person_record.get("id")
    credits = Get_person_tv_credits(person_id)
    cast = safe_get(credits, "cast", default=[])
    if not cast:
        return None

    best_match = None
    best_score = -1

    for credit in cast[:MAX_CREDITS_TO_SCAN]:
        name = normalize_text(credit.get("name"))
        original_name = normalize_text(credit.get("original_name"))
        score = float(credit.get("popularity") or 0)

        for keyword in TARGET_SHOW_KEYWORDS:
            if keyword in name or keyword in original_name:
                score += 1000.0

        if score > best_score:
            best_score = score
            best_match = credit

    return best_match if best_match else cast[0]


def get_show_credits(tv_show_record):
    if not tv_show_record:
        return None

    series_id = tv_show_record.get("id")
    credits = Get_tv_episode_credits(series_id, DEFAULT_SEASON_NUMBER, DEFAULT_EPISODE_NUMBER)
    return credits


def determine_who_worked_with_jeremy(credits, person_record):
    collaborators = []

    if not credits or not person_record:
        return collaborators

    jeremy_id = person_record.get("id")
    jeremy_name = normalize_text(person_record.get("name"))

    cast = safe_get(credits, "cast", default=[])
    crew = safe_get(credits, "crew", default=[])
    guest_stars = safe_get(credits, "guest_stars", default=[])

    seen = set()

    def add_entry(entry, role_type):
        if not isinstance(entry, dict):
            return
        person_id = entry.get("id")
        name = entry.get("name")
        if person_id is None or not name:
            return
        if person_id == jeremy_id or normalize_text(name) == jeremy_name:
            return
        key = (person_id, name, role_type)
        if key in seen:
            return
        seen.add(key)
        collaborators.append({
            "id": person_id,
            "name": name,
            "role_type": role_type,
            "character": entry.get("character"),
            "job": entry.get("job"),
            "department": entry.get("department"),
        })

    for entry in cast:
        add_entry(entry, "cast")

    for entry in crew:
        add_entry(entry, "crew")

    for entry in guest_stars:
        add_entry(entry, "guest_star")

    return collaborators


def format_collaborators_output(tv_show_record, collaborators):
    show_name = ""
    if isinstance(tv_show_record, dict):
        show_name = tv_show_record.get("name") or tv_show_record.get("original_name") or ""

    lines = []
    lines.append(f"Most popular TV show found: {show_name if show_name else 'Unknown'}")
    lines.append("People who worked with Jeremy Clarkson in that show/episode:")

    if not collaborators:
        lines.append("- No collaborators found in the retrieved episode credits.")
        return "\n".join(lines)

    for person in collaborators:
        role_bits = []
        if person.get("role_type"):
            role_bits.append(person["role_type"])
        if person.get("character"):
            role_bits.append(f"character: {person['character']}")
        if person.get("job"):
            role_bits.append(f"job: {person['job']}")
        if person.get("department"):
            role_bits.append(f"department: {person['department']}")
        role_text = "; ".join(role_bits) if role_bits else "role info unavailable"
        lines.append(f"- {person['name']} ({role_text})")

    return "\n".join(lines)


def run():
    person_record = search_jeremy_clarkson()
    tv_show_record = get_most_popular_tv_show(person_record)
    credits = get_show_credits(tv_show_record)
    collaborators = determine_who_worked_with_jeremy(credits, person_record)
    output = format_collaborators_output(tv_show_record, collaborators)
    print(output)


if __name__ == "__main__":
    try:
        run()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

