from Search_tv import Search_tv
from Get_tv_episode_details import Get_tv_episode_details
from Get_person_details import Get_person_details

import traceback

BLACK_MIRROR_QUERY = "Black Mirror"
SECOND_SEASON_NUMBER = 2
FIRST_EPISODE_NUMBER = 1


def safe_get(dct, path, default=None):
    current = dct
    for key in path:
        if not isinstance(current, dict):
            return default
        if key not in current:
            return default
        current = current[key]
    return current


def select_matching_series(search_results, series_name):
    results = search_results.get("results", []) if isinstance(search_results, dict) else []
    target = (series_name or "").strip().lower()
    if not results:
        return None

    exact_name_matches = []
    loose_name_matches = []
    for item in results:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name", "")).strip().lower()
        original_name = str(item.get("original_name", "")).strip().lower()
        if name == target or original_name == target:
            exact_name_matches.append(item)
        if target and (target in name or target in original_name):
            loose_name_matches.append(item)

    if exact_name_matches:
        return exact_name_matches[0]
    if loose_name_matches:
        return loose_name_matches[0]
    return results[0]


def get_series_record(series_name):
    search_results = Search_tv(series_name)
    return select_matching_series(search_results, series_name)


def get_first_episode_of_second_season(series_record):
    if not series_record:
        return None
    series_id = series_record.get("id")
    if series_id is None:
        return None
    return Get_tv_episode_details(series_id, SECOND_SEASON_NUMBER, FIRST_EPISODE_NUMBER)


def identify_lead_actor_from_episode(episode_details):
    if not episode_details:
        return None

    guest_stars = episode_details.get("guest_stars", [])
    if not isinstance(guest_stars, list):
        guest_stars = []

    if guest_stars:
        sorted_stars = sorted(
            [star for star in guest_stars if isinstance(star, dict)],
            key=lambda x: (x.get("order", 10**9), -float(x.get("popularity", 0) or 0))
        )
        lead_star = sorted_stars[0] if sorted_stars else None
        if lead_star and lead_star.get("id") is not None:
            return lead_star

    crew = episode_details.get("crew", [])
    if isinstance(crew, list):
        for member in crew:
            if not isinstance(member, dict):
                continue
            job = str(member.get("job", "")).strip().lower()
            if "director" in job and member.get("id") is not None:
                return member

    return None


def get_actor_appearance(person_record):
    if not person_record:
        return None
    person_id = person_record.get("id")
    if person_id is None:
        return None
    return Get_person_details(person_id)


def build_appearance_summary(person_details):
    if not person_details:
        return "No person details available."

    name = person_details.get("name", "Unknown")
    profile_path = person_details.get("profile_path")
    known_for_department = person_details.get("known_for_department", "Unknown")
    place_of_birth = person_details.get("place_of_birth", "Unknown")
    birthday = person_details.get("birthday", "Unknown")

    lines = [
        f"Lead actor: {name}",
        f"Known for: {known_for_department}",
        f"Born: {birthday}",
        f"Birthplace: {place_of_birth}",
        f"Profile image path: {profile_path if profile_path else 'Not available'}",
    ]
    return "\n".join(lines)


def main():
    series_record = get_series_record(BLACK_MIRROR_QUERY)
    episode_details = get_first_episode_of_second_season(series_record)
    lead_actor = identify_lead_actor_from_episode(episode_details)
    person_details = get_actor_appearance(lead_actor)
    summary = build_appearance_summary(person_details)
    print(summary)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

