MAX_POPULAR_TV_SHOWS = 1

def get_most_popular_tv_airing_today():
    try:
        response = Get_airing_today_tv()
        results = response.get("results", [])
        results.sort(key=lambda x: x.get("popularity", 0), reverse=True)
