import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_person import Search_person
from Get_person_tv_credits import Get_person_tv_credits

import traceback

# Module-level pinned constants
TARGET_PERSON_NAME = "David Schwimmer"
TARGET_PERSON_NAME_NORMALIZED = TARGET_PERSON_NAME.lower().strip()


def search_person_by_name(name):
    if name is None:
        raise ValueError("name is required")
    return Search_person(name)


def select_matching_person(person_results, target_name):
    if not isinstance(person_results, dict):
        return None

    results = person_results.get("results", [])
    if not isinstance(results, list) or not results:
        return None

    target_normalized = (target_name or "").lower().strip()

    for person in results:
        if not isinstance(person, dict):
            continue
        person_name = str(person.get("name", "")).lower().strip()
        original_name = str(person.get("original_name", "")).lower().strip()
        if target_normalized in person_name or target_normalized in original_name:
            return person

    return results[0] if results else None


def get_person_tv_credits(person_id):
    if person_id is None:
        raise ValueError("person_id is required")
    return Get_person_tv_credits(person_id)


def determine_most_popular_tv_show(tv_credits):
    if not isinstance(tv_credits, dict):
        return None

    cast = tv_credits.get("cast", [])
    if not isinstance(cast, list) or not cast:
        return None

    best_show = None
    best_popularity = float("-inf")

    for credit in cast:
        if not isinstance(credit, dict):
            continue
        popularity = credit.get("popularity")
        name = credit.get("name")
        if name is None:
            continue
        try:
            popularity_value = float(popularity)
        except (TypeError, ValueError):
            continue

        if popularity_value > best_popularity:
            best_popularity = popularity_value
            best_show = credit

    return best_show


def format_show_output(person_name, show):
    if not show:
        return f"No TV show credits found for {person_name}."

    show_name = show.get("name", "Unknown")
    popularity = show.get("popularity", "Unknown")
    first_air_date = show.get("first_air_date", "Unknown")

    return (
        f"David Schwimmer's most popular TV show is: {show_name}\n"
        f"Popularity: {popularity}\n"
        f"First air date: {first_air_date}"
    )


def main():
    person_results = search_person_by_name(TARGET_PERSON_NAME)
    matching_person = select_matching_person(person_results, TARGET_PERSON_NAME_NORMALIZED)

    if not matching_person:
        print(f"No matching person found for {TARGET_PERSON_NAME}.")
        return

    person_id = matching_person.get("id")
    if person_id is None:
        print(f"Matching person found, but no ID was available for {TARGET_PERSON_NAME}.")
        return

    tv_credits = get_person_tv_credits(person_id)
    most_popular_show = determine_most_popular_tv_show(tv_credits)
    output = format_show_output(TARGET_PERSON_NAME, most_popular_show)
    print(output)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

import sys
from pathlib import Path
