from Search_tv import Search_tv
from Get_tv_details import Get_tv_details
from Get_tv_season_details import Get_tv_season_details
from Get_tv_episode_details import Get_tv_episode_details

import traceback

BLACK_MIRROR_QUERY = "Black Mirror"
TARGET_SEASON_NUMBER = 2
TARGET_EPISODE_NUMBER = 3
TARGET_SERIES_NAME = "Black Mirror"


def search_series(query):
    try:
        return Search_tv(query)
    except Exception as exc:
        raise RuntimeError(f"Failed to search TV series for query={query!r}") from exc


def find_matching_show_id(search_result, target_name):
    results = search_result.get("results", []) if isinstance(search_result, dict) else []
    target_lower = target_name.lower()
    for item in results:
        name = item.get("name", "")
        original_name = item.get("original_name", "")
        if target_lower in name.lower() or target_lower in original_name.lower():
            return item.get("id")
    if results:
        return results[0].get("id")
    return None


def get_series_details(series_id):
    try:
        return Get_tv_details(series_id)
    except Exception as exc:
        raise RuntimeError(f"Failed to get TV details for series_id={series_id}") from exc


def get_season_details(series_id, season_number):
    try:
        return Get_tv_season_details(series_id, season_number)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to get season details for series_id={series_id}, season_number={season_number}"
        ) from exc


def get_episode_details(series_id, season_number, episode_number):
    try:
        return Get_tv_episode_details(series_id, season_number, episode_number)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to get episode details for series_id={series_id}, season_number={season_number}, episode_number={episode_number}"
        ) from exc


def extract_director_from_episode_details(episode_details):
    crew = episode_details.get("crew", []) if isinstance(episode_details, dict) else []
    for member in crew:
        job = member.get("job", "")
        department = member.get("department", "")
        if "director" in job.lower() or "directing" in department.lower():
            name = member.get("name")
            if name:
                return name
    return None


def determine_director_for_black_mirror():
    search_result = search_series(BLACK_MIRROR_QUERY)
    show_id = find_matching_show_id(search_result, TARGET_SERIES_NAME)
    if show_id is None:
        raise RuntimeError("Could not determine a matching series ID for Black Mirror.")

    get_series_details(show_id)
    get_season_details(show_id, TARGET_SEASON_NUMBER)
    episode_details = get_episode_details(show_id, TARGET_SEASON_NUMBER, TARGET_EPISODE_NUMBER)

    director = extract_director_from_episode_details(episode_details)
    return director


def main():
    director = determine_director_for_black_mirror()
    if director:
        print(director)
    else:
        print("Director not found.")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

