from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits
from Get_movie_details import Get_movie_details

import requests
import traceback



PERSON_QUERY = "Christopher Nolan"
NOTABLE_VOTE_AVERAGE_THRESHOLD = 7.0
MAX_RETRIES = 3

def search_for_christopher_nolan_id():
    response = Search_person(PERSON_QUERY)
    results = response.get("results", [])
    if results:
        christopher_nolan = next((person for person in results if person.get("name") == PERSON_QUERY), None)
        if christopher_nolan:
            return christopher_nolan.get("id")
    return None

def get_christopher_nolan_movie_credits(person_id):
    response = Get_person_movie_credits(person_id)
    return response.get("cast", [])

def list_notable_movies(movie_credits):
    notable_movies = []
    for movie_credit in movie_credits:
        movie_id = movie_credit.get("id")
        retries = 0
        while retries < MAX_RETRIES:
            try:
                movie_details = Get_movie_details(movie_id)
                break
            except requests.exceptions.ConnectionError as e:
                retries += 1
                if retries == MAX_RETRIES:
                    raise Exception(f"Failed to retrieve movie details after {MAX_RETRIES} retries: {e}")
        if movie_details.get("vote_average", 0) >= NOTABLE_VOTE_AVERAGE_THRESHOLD:
            notable_movies.append({
                "title": movie_details.get("title"),
                "vote_average": movie_details.get("vote_average"),
                "release_date": movie_details.get("release_date")
            })
    return notable_movies

def main():
    try:
        christopher_nolan_id = search_for_christopher_nolan_id()
        if christopher_nolan_id is None:
            print("Christopher Nolan not found.")
            return
        movie_credits = get_christopher_nolan_movie_credits(christopher_nolan_id)
        notable_movies = list_notable_movies(movie_credits)
        for movie in notable_movies:
            print(f"Title: {movie['title']}, Vote Average: {movie['vote_average']}, Release Date: {movie['release_date']}")
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

