from Search_movie import Search_movie
from Get_movie_details import Get_movie_details
from Get_movie_details import Get_movie_details

import traceback

MOVIE_AVATAR_QUERY = 'Avatar'
MOVIE_AVATAR_THE_WAY_OF_WATER_QUERY = 'Avatar: The Way of Water'

def search_movie_avatar():
    return Search_movie(MOVIE_AVATAR_QUERY)

def get_details_avatar(movie_avatar_result):
    movie_id = movie_avatar_result['results'][0]['id']
    return Get_movie_details(movie_id)

def search_movie_avatar_the_way_of_water():
    return Search_movie(MOVIE_AVATAR_THE_WAY_OF_WATER_QUERY)

def get_details_avatar_the_way_of_water(movie_avatar_the_way_of_water_result):
    movie_id = movie_avatar_the_way_of_water_result['results'][0]['id']
    return Get_movie_details(movie_id)

def compare_ratings(details_avatar, details_avatar_the_way_of_water):
    rating_avatar = details_avatar['vote_average']
    rating_avatar_the_way_of_water = details_avatar_the_way_of_water['vote_average']
    if rating_avatar > rating_avatar_the_way_of_water:
        return details_avatar['title']
    else:
        return details_avatar_the_way_of_water['title']

def main():
