        details_avatar = get_details_avatar(movie_avatar_result)
        movie_avatar_the_way_of_water_result = search_movie_avatar_the_way_of_water()
        details_avatar_the_way_of_water = get_details_avatar_the_way_of_water(movie_avatar_the_way_of_water_result)
