from Search_tv import Search_tv
from Get_tv_season_details import Get_tv_season_details
from Get_tv_season_images import Get_tv_season_images

import traceback

# Module-level pinned constants
SERIES_QUERY = "Big Bang Theory"
TARGET_SEASON_NUMBER = 2
POSTER_BASE_URL = "https://image.tmdb.org/t/p/original"


def search_series_identifier(query):
    """
    Search for a TV series and return the best matching series ID.
    """
    try:
        response = Search_tv(query)
        results = response.get("results", [])
        if not results:
            return None

        # Prefer an exact-ish name match, but fall back gracefully.
        normalized_query = query.lower().strip()
        best_item = None

        for item in results:
            name = str(item.get("name", "")).lower().strip()
            original_name = str(item.get("original_name", "")).lower().strip()
            if normalized_query in name or normalized_query in original_name:
                best_item = item
                break

        if best_item is None:
            best_item = results[0]

        return best_item.get("id")
    except Exception:
        raise


def get_season_details(series_id, season_number):
    """
    Fetch season details for a given series and season number.
    """
    if series_id is None:
        return None
    try:
        return Get_tv_season_details(series_id, season_number)
    except Exception:
        raise


def get_season_images(series_id, season_number):
    """
    Fetch season image metadata for a given series and season number.
    """
    if series_id is None:
        return None
    try:
        return Get_tv_season_images(series_id, season_number)
    except Exception:
        raise


def select_best_poster_image(season_details, season_images):
    """
    Select the most appropriate poster image from season images, using the season
    details poster_path as a hint when available.
    """
    if not isinstance(season_images, dict):
        return None

    posters = season_images.get("posters", [])
    if not posters:
        return None

    season_poster_path = None
    if isinstance(season_details, dict):
        season_poster_path = season_details.get("poster_path")

    if season_poster_path:
        for poster in posters:
            file_path = poster.get("file_path", "")
            if file_path and season_poster_path in file_path:
                return poster

    # Prefer higher vote_average, then vote_count, then larger resolution.
    def poster_sort_key(p):
        return (
            p.get("vote_average", 0),
            p.get("vote_count", 0),
            p.get("width", 0) * p.get("height", 0),
        )

    return sorted(posters, key=poster_sort_key, reverse=True)[0]


def format_poster_output(poster_image, season_details):
    """
    Format the selected poster image into a readable, task-oriented output.
    """
    if not poster_image:
        season_name = None
        if isinstance(season_details, dict):
            season_name = season_details.get("name")
        print(f"No poster image found for {season_name or 'the requested season'}.")
        return

    file_path = poster_image.get("file_path")
    full_url = f"{POSTER_BASE_URL}{file_path}" if file_path else None

    season_name = None
    season_number = None
    if isinstance(season_details, dict):
        season_name = season_details.get("name")
        season_number = season_details.get("season_number")

    print("Poster found:")
    if season_name is not None:
        print(f"Season: {season_name}")
    if season_number is not None:
        print(f"Season number: {season_number}")
    if full_url is not None:
        print(f"Poster URL: {full_url}")
    else:
        print("Poster URL: unavailable")
    print(f"Image file path: {file_path or 'unavailable'}")
    print(f"Dimensions: {poster_image.get('width', 'unknown')}x{poster_image.get('height', 'unknown')}")
    print(f"Average vote: {poster_image.get('vote_average', 'unknown')}")
    print(f"Vote count: {poster_image.get('vote_count', 'unknown')}")


def main():
    series_id = search_series_identifier(SERIES_QUERY)
    season_details = get_season_details(series_id, TARGET_SEASON_NUMBER)
    season_images = get_season_images(series_id, TARGET_SEASON_NUMBER)
    poster_image = select_best_poster_image(season_details, season_images)
    format_poster_output(poster_image, season_details)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

