from Get_tv_season_details import Get_tv_season_details
from Get_tv_episode_details import Get_tv_episode_details

import traceback

# Module-level pinned constants derived from user requirement
SERIES_QUERY = "Mandalorian"
SEASON_NUMBER = 2
EPISODE_NUMBER = 3

# Explicit schema-grounded key mappings
TV_SEARCH_RESULTS_KEY = "results"
TV_SEARCH_NAME_KEY = "name"
TV_SEARCH_ID_KEY = "id"

SEASON_DETAILS_EPISODES_KEY = "episodes"
SEASON_DETAILS_NAME_KEY = "name"
EPISODE_DETAILS_NAME_KEY = "name"


def search_series(series_query):
    try:
        return Search_tv(series_query)
    except Exception as exc:
        raise RuntimeError(f"Failed to search TV series for query '{series_query}': {exc}") from exc


def select_target_series(series_search_results, requested_title):
    results = series_search_results.get(TV_SEARCH_RESULTS_KEY, [])
    if not results:
        return None

    requested_lower = requested_title.lower()
    chosen = None

    for item in results:
        name = str(item.get(TV_SEARCH_NAME_KEY, ""))
        if requested_lower in name.lower() or name.lower() in requested_lower:
            chosen = item
            break

    if chosen is None:
        chosen = results[0]

    return chosen.get(TV_SEARCH_ID_KEY)


def get_season_details(series_id, season_number):
    try:
        return Get_tv_season_details(series_id, season_number)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to get season details for series_id={series_id}, season_number={season_number}: {exc}"
        ) from exc


def get_episode_details(series_id, season_number, episode_number):
    try:
        return Get_tv_episode_details(series_id, season_number, episode_number)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to get episode details for series_id={series_id}, season_number={season_number}, episode_number={episode_number}: {exc}"
        ) from exc


def extract_episode_name(episode_details):
    return episode_details.get(EPISODE_DETAILS_NAME_KEY, "")


def resolve_episode_name():
    search_response = search_series(SERIES_QUERY)
    series_id = select_target_series(search_response, SERIES_QUERY)

    if series_id is None:
        raise RuntimeError(f"No TV series found for query '{SERIES_QUERY}'.")

    season_details = get_season_details(series_id, SEASON_NUMBER)

    episodes = season_details.get(SEASON_DETAILS_EPISODES_KEY, [])
    if episodes:
        matched_episode = None
        for episode in episodes:
            if episode.get("episode_number") == EPISODE_NUMBER:
                matched_episode = episode
                break
        # The season details are fetched for validation/context; episode name is taken from episode details below.

    episode_details = get_episode_details(series_id, SEASON_NUMBER, EPISODE_NUMBER)
    episode_name = extract_episode_name(episode_details)
    return episode_name


def main():
    episode_name = resolve_episode_name()
    print(episode_name)


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

