from Get_tv_details import Get_tv_details
from Get_movie_credits import Get_movie_credits
from Get_person_details import Get_person_details

import traceback

# Module-level pinned constants derived from the user requirement.
TWIN_PEAKS_TITLE = "Twin Peaks"
TWIN_PEAKS_SEASON_NUMBER = 1
MULHOLLAND_DRIVE_TITLE = "Mulholland Drive"
DIRECTOR_JOB_KEYWORDS = ("director", "directed by", "direction")


def safe_get(data, path, default=None):
    cur = data
    for key in path:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur[key]
    return cur


def find_best_tv_match_for_title(title):
    # The available API is only by ID, so this function provides a clear, modular
    # place for lookup assumptions. Since no search API exists, the required IDs
    # must be pinned if known from the task context. Here we use the commonly
    # recognized TMDB ID for Twin Peaks.
    mapping = {
        "Twin Peaks": 1964,
    }
    return mapping.get(title)


def find_best_movie_match_for_title(title):
    # The available API is only by ID, so this function provides a clear, modular
    # place for lookup assumptions. Since no search API exists, the required IDs
    # must be pinned if known from the task context. Here we use the commonly
    # recognized TMDB ID for Mulholland Drive.
    mapping = {
        "Mulholland Drive": 1018,
    }
    return mapping.get(title)


def get_tv_director_reference(series_id, season_number):
    tv_details = Get_tv_details(series_id)
    seasons = tv_details.get("seasons", [])
    season_match = None
    for season in seasons:
        if isinstance(season, dict) and season.get("season_number") == season_number:
            season_match = season
            break

    # The TV detail schema does not expose crew/director fields.
    # We return the series creator as the closest available person reference.
    created_by = tv_details.get("created_by", [])
    if created_by:
        first_creator = created_by[0]
        return first_creator.get("id"), {
            "source": "created_by",
            "series_name": tv_details.get("name"),
            "season_number": season_number,
            "season_name": season_match.get("name") if season_match else None,
        }

    return None, {
        "source": "none",
        "series_name": tv_details.get("name"),
        "season_number": season_number,
        "season_name": season_match.get("name") if season_match else None,
    }


def get_movie_director_reference(movie_id):
    credits = Get_movie_credits(movie_id)
    crew = credits.get("crew", [])
    director_candidates = []

    for member in crew:
        if not isinstance(member, dict):
            continue
        job = str(member.get("job", "")).lower()
        department = str(member.get("department", "")).lower()
        if any(keyword in job for keyword in DIRECTOR_JOB_KEYWORDS) or "direct" in department:
            director_candidates.append(member)

    if director_candidates:
        director = director_candidates[0]
        return director.get("id"), {
            "source": "crew",
            "movie_id": movie_id,
            "credit_name": director.get("name"),
            "job": director.get("job"),
        }

    return None, {
        "source": "none",
        "movie_id": movie_id,
    }


def resolve_person_identity(person_id):
    if person_id is None:
        return None
    person_details = Get_person_details(person_id)
    return {
        "id": person_details.get("id"),
        "name": person_details.get("name"),
        "known_for_department": person_details.get("known_for_department"),
        "imdb_id": person_details.get("imdb_id"),
        "birthday": person_details.get("birthday"),
        "place_of_birth": person_details.get("place_of_birth"),
    }


def compare_person_identities(identity_a, identity_b):
    if not identity_a or not identity_b:
        return False
    id_a = identity_a.get("id")
    id_b = identity_b.get("id")
    if id_a is not None and id_b is not None:
        return id_a == id_b
    name_a = str(identity_a.get("name", "")).strip().lower()
    name_b = str(identity_b.get("name", "")).strip().lower()
    return bool(name_a and name_b and name_a == name_b)


def main():
    twin_peaks_series_id = find_best_tv_match_for_title(TWIN_PEAKS_TITLE)
    mulholland_drive_movie_id = find_best_movie_match_for_title(MULHOLLAND_DRIVE_TITLE)

    twin_peaks_director_reference, twin_meta = get_tv_director_reference(
        twin_peaks_series_id, TWIN_PEAKS_SEASON_NUMBER
    )
    mulholland_drive_director_reference, mul_meta = get_movie_director_reference(
        mulholland_drive_movie_id
    )

    twin_peaks_director_identity = resolve_person_identity(twin_peaks_director_reference)
    mulholland_drive_director_identity = resolve_person_identity(mulholland_drive_director_reference)

    same_person = compare_person_identities(
        twin_peaks_director_identity, mulholland_drive_director_identity
    )

    if same_person:
        print("Yes — the director reference for Twin Peaks Season 1 and Mulholland Drive appears to be the same person.")
    else:
        print("No — the director reference for Twin Peaks Season 1 and Mulholland Drive does not appear to be the same person.")

    print(f"Twin Peaks Season 1 director reference: {twin_peaks_director_identity.get('name') if twin_peaks_director_identity else 'Unavailable'}")
    print(f"Mulholland Drive director reference: {mulholland_drive_director_identity.get('name') if mulholland_drive_director_identity else 'Unavailable'}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

