from Get_movie_details import Get_movie_details
from Get_person_details import Get_person_details
from Get_person_details import Get_person_details

import requests
import traceback
import time


from Get_movie_credits import Get_movie_credits

MOVIE_TITLE = "Mulholland Drive"
MOVIE_ID = 406  # Assuming this is the ID for "Mulholland Drive"
MAX_RETRIES = 3
RETRY_DELAY = 1  # seconds

def SearchMovieDirector():
    movie_details = Get_movie_details(MOVIE_ID)
    crew_details = Get_movie_credits(MOVIE_ID)
    for crew_member in crew_details['crew']:
        if crew_member['job'].lower() == 'director':
            return crew_member['id']
    return None

def GetDirectorDetails(director_id):
    return Get_person_details(director_id)

def ExtractBirthplace(director_details):
    return director_details.get('place_of_birth')

def robust_request(func, *args, **kwargs):
    for attempt in range(MAX_RETRIES):
        try:
            return func(*args, **kwargs)
        except requests.exceptions.ConnectionError as e:
            if attempt < MAX_RETRIES - 1:
                print(f"Connection error: {e}. Retrying in {RETRY_DELAY} seconds...")
                time.sleep(RETRY_DELAY)
            else:
                raise

def main():
    try:
        director_id = SearchMovieDirector()
        if director_id is None:
            raise Exception("Director not found")
        director_details = robust_request(GetDirectorDetails, director_id)
        birthplace = ExtractBirthplace(director_details)
        print(birthplace)
    except Exception as e:
