from Get_person_movie_credits import Get_person_movie_credits
from Search_person import Search_person
from Get_person_movie_credits import Get_person_movie_credits

import traceback
import requests
import time



DIRECTOR_JOB_TITLE = "Director"
KUROSAWA_NAME = "Akira Kurosawa"
SPIELBERG_NAME = "Spielberg"
MAX_RETRIES = 3
RETRY_DELAY = 1  # seconds

def search_person_id(name):
    response = Search_person(name)
    results = response.get("results", [])
    if results:
        return results[0].get("id")
    return None

def get_person_movie_credits(person_id):
    retries = 0
    while retries < MAX_RETRIES:
        try:
            response = Get_person_movie_credits(person_id)
            return response
        except (requests.exceptions.ConnectionError, ConnectionResetError) as e:
            retries += 1
            if retries < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                raise Exception(f"Failed to retrieve movie credits after {MAX_RETRIES} retries: {e}")

def count_directed_movies(movie_credits):
    crew_credits = movie_credits.get("crew", [])
    directed_movies = [credit for credit in crew_credits if credit.get("job") == DIRECTOR_JOB_TITLE]
    return len(directed_movies)

def compare_directed_movies(count1, count2):
    if count1 > count2:
        return f"{KUROSAWA_NAME} directed more movies."
    elif count2 > count1:
        return f"{SPIELBERG_NAME} directed more movies."
    else:
        return "Both directors have directed the same number of movies."

def main():
    try:
        kurosawa_id = search_person_id(KUROSAWA_NAME)
        kurosawa_credits = get_person_movie_credits(kurosawa_id)
        kurosawa_directed = count_directed_movies(kurosawa_credits)

        spielberg_id = search_person_id(SPIELBERG_NAME)
        spielberg_credits = get_person_movie_credits(spielberg_id)
        spielberg_directed = count_directed_movies(spielberg_credits)

        result = compare_directed_movies(kurosawa_directed, spielberg_directed)
        print(result)
    except Exception as e:
        traceback.print_exc(file=sys.stderr)

if __name__ == "__main__":
    main()

