import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
RESTBENCH_TOOLS_DIR = PROJECT_ROOT / 'restbench tools'
if str(RESTBENCH_TOOLS_DIR) not in sys.path:
    sys.path.insert(0, str(RESTBENCH_TOOLS_DIR))

from Search_movie import Search_movie
from Get_movie_credits import Get_movie_credits

import traceback

# Module-level pinned constants derived from the user requirement
TARGET_MOVIE_TITLE = "We Married as Job"
TARGET_PERSON_A = "Yui Aragaki"
TARGET_PERSON_B = "Gen Hoshino"


def search_for_movie_identifier(movie_title):
    """
    Search for the target movie title and return the best matching movie identifier.
    """
    try:
        search_result = Search_movie(movie_title)
    except Exception as exc:
        raise RuntimeError(f"Movie search failed for title '{movie_title}': {exc}") from exc

    results = search_result.get("results", [])
    if not results:
        return None

    normalized_target = movie_title.strip().lower()
    exact_title_match = None
    partial_title_match = None

    for item in results:
        title = str(item.get("title", "")).strip()
        original_title = str(item.get("original_title", "")).strip()
        title_l = title.lower()
        original_title_l = original_title.lower()

        if title_l == normalized_target or original_title_l == normalized_target:
            exact_title_match = item
            break

        if normalized_target in title_l or normalized_target in original_title_l:
            if partial_title_match is None:
                partial_title_match = item

    chosen = exact_title_match or partial_title_match or results[0]
    return chosen.get("id")


def retrieve_movie_credits(movie_identifier):
    """
    Retrieve cast and crew data for the given movie identifier.
    """
    if movie_identifier is None:
        return None

    try:
        credits_result = Get_movie_credits(movie_identifier)
    except Exception as exc:
        raise RuntimeError(f"Movie credits retrieval failed for movie ID '{movie_identifier}': {exc}") from exc

    return credits_result


def check_cast_membership(credits_result, person_a, person_b):
    """
    Check whether both people appear in the cast list.
    """
    if not isinstance(credits_result, dict):
        return False

    cast_list = credits_result.get("cast", [])
    if not isinstance(cast_list, list):
        return False

    cast_names = []
    for member in cast_list:
        if isinstance(member, dict):
            name = member.get("name")
            if isinstance(name, str) and name.strip():
                cast_names.append(name.strip().lower())

    a_found = person_a.strip().lower() in cast_names
    b_found = person_b.strip().lower() in cast_names
    return a_found and b_found


def main():
    movie_identifier = search_for_movie_identifier(TARGET_MOVIE_TITLE)
    credits_result = retrieve_movie_credits(movie_identifier)
    co_starring = check_cast_membership(credits_result, TARGET_PERSON_A, TARGET_PERSON_B)

    if co_starring:
        print(f"Yes — both {TARGET_PERSON_A} and {TARGET_PERSON_B} appear in the cast of '{TARGET_MOVIE_TITLE}'.")
    else:
        print(f"No — both {TARGET_PERSON_A} and {TARGET_PERSON_B} do not appear together in the cast of '{TARGET_MOVIE_TITLE}'.")

    return co_starring


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        raise

