from Search_tv import Search_tv
from Get_tv_episode_credits import Get_tv_episode_credits
from Get_person_details import Get_person_details

import traceback
from datetime import datetime

MOVIE_QUERY = "Barbie"
TV_QUERY = "DEATH NOTE"
TV_SEASON_NUMBER = 1
TV_EPISODE_NUMBER = 1

def search_movie_barbie():
    response = Search_movie(MOVIE_QUERY)
    results = response.get("results", [])
    if results:
        return results[0].get("id")
    return None

def get_director_details(movie_id):
    response = Get_movie_credits(movie_id)
    crew = response.get("crew", [])
    for member in crew:
        if member.get("job") == "Director":
            return member.get("id")
    return None

def get_director_age(person_id):
    response = Get_person_details(person_id)
    birthday = response.get("birthday")
    if birthday:
        birth_date = datetime.strptime(birthday, "%Y-%m-%d")
        age = (datetime.now() - birth_date).days // 365
        return age
    return None

def search_tv_death_note():
    response = Search_tv(TV_QUERY)
    results = response.get("results", [])
    if results:
        return results[0].get("id")
    return None

def get_lead_actor_details(tv_id):
    response = Get_tv_episode_credits(tv_id, TV_SEASON_NUMBER, TV_EPISODE_NUMBER)
    cast = response.get("cast", [])
    if cast:
        return cast[0].get("id")
    return None

def get_lead_actor_age(person_id):
    response = Get_person_details(person_id)
    birthday = response.get("birthday")
    if birthday:
        birth_date = datetime.strptime(birthday, "%Y-%m-%d")
        age = (datetime.now() - birth_date).days // 365
        return age
    return None

def compare_ages(director_age, lead_actor_age):
    if director_age is None or lead_actor_age is None:
        return "Unable to compare ages due to missing data."
    age_diff = abs(director_age - lead_actor_age)
    if director_age > lead_actor_age:
        return f"The director is older by {age_diff} years."
    elif lead_actor_age > director_age:
        return f"The lead actor is older by {age_diff} years."
    else:
        return "The director and the lead actor are of the same age."

def main():
    movie_id = search_movie_barbie()
    director_person_id = get_director_details(movie_id)
    director_age = get_director_age(director_person_id)

    tv_id = search_tv_death_note()
    lead_actor_person_id = get_lead_actor_details(tv_id)
    lead_actor_age = get_lead_actor_age(lead_actor_person_id)

    result = compare_ages(director_age, lead_actor_age)
    print(result)

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

